entries[444067] = { ["name"] = "Void Reaper's Contract", ["text"] = "Approximately 3 procs per minute\nYour abilities have a high chance to summon a phantom ethereal, dealing ( 1 * 600 ) Shadow damage to your target and [source value] Shadow damage to all other enemies caught in its path.\n\nIf the target is below 35% health, this effect summons two additional phantoms at 25% effectiveness.\n(1s cooldown)", ["unresolvedValues"] = true }
entries[444068] = { ["name"] = "Vambraces of Deepening Darkness", ["text"] = "2 sec cast 3\nReagents:\nVial of Kaheti Oils (2), Kaheti Swarm Chitin (10), Writhing Hide (2), Chitin Armor Banding , Spark (#256)\nOptional Reagents:\nDrop:\nWorld Creatures\n\nVambraces of Deepening Darkness\nBinds when picked up\nWrist Mail\n2317 Armor\n+1,198 [Agility or Intellect]+5,483 Stamina\n+ 351 Versatility\n+ 468 Mastery\nDurability 55 / 55\nEquip: Dealing damage has a chance to grant you a stack of Deepening Darkness. The Darkness erupts at 5 stacks, dealing ( 1 * 161232 ) Shadow damage split among all nearby enemies. Damage increases per target, up to 5. Afterwards, the shadows weigh you down and lower your movement speed by 15% for 5 sec.\n\nThis is a Nerubian embellishment.\n80" }
entries[444069] = { ["name"] = "Fury of the Horsemen", ["text"] = "Every 50 Runic Power you spend extends the duration of the Horsemen's aid in combat by 1 sec, up to 5 sec." }
entries[444070] = { ["name"] = "Adrenal Surge Clasp", ["text"] = "2 sec cast 3\nReagents:\nVial of Kaheti Oils (2), Kaheti Swarm Chitin (10), Writhing Hide (2), Chitin Armor Banding , Spark (#256)\nOptional Reagents:\nDrop:\nSikran, Captain of the Sureki\nZone:\nNerub-ar Palace\nRecipe:\nPurchasable on the Auction House\n\nAdrenal Surge Clasp\nBinds when picked up\nWaist Leather\n1767 Armor\n+1,597 [Agility or Intellect]+7,311 Stamina\n+ 624 Critical Strike\n+ 468 Versatility\nDurability 55 / 55\nEquip: Taking damage has a chance to grant you an Adrenal Surge, causing you to gain 1265 Primary Stat and lose 207 Mastery for 12 sec.\n\nThis is a Nerubian embellishment. (15s cooldown)\n80" }
entries[444071] = { ["name"] = "Waders of the Unifying Flame", ["text"] = "2 sec cast 3\nReagents:\nProfaned Tinderbox (2), Stormcharged Leather (150), Crystalfused Hide (3), Chitin Armor Banding , Spark (#256)\nOptional Reagents:\nDrop:\nPrioress Murrpray\nZone:\nPriory of the Sacred Flame\n\nWaders of the Unifying Flame\nBinds when picked up\nFeet Leather\n1964 Armor\n+1,597 [Agility or Intellect]+7,311 Stamina\n+ 624 Haste\n+ 468 Mastery\nDurability 80 / 80\nEquip: Healing an ally has a chance to grant you both a Unifying Ember. When two Unifying Embers contact each other, they erupt into Unifying Flames.\n\nUnifying Flames grants the wearer 1175 of their highest secondary stat, and others 235 of a random secondary stat.\n80" }
entries[444072] = { ["name"] = "A Feast of Souls", ["text"] = "While you have 2 or more Horsemen aiding you, your Runic Power spending abilities deal 20% increased damage." }
entries[444073] = { ["name"] = "Sanctified Torchbearer's Grips", ["text"] = "2 sec cast 3\nReagents:\nProfaned Tinderbox (3), Gloom Chitin (150), Crystalfused Hide (3), Chitin Armor Banding , Spark (#256)\nOptional Reagents:\nQuest:\nSpreading the Light\n\nSanctified Torchbearer's Grips\nBinds when picked up\nHands Mail\n2606 Armor\n+1,597 [Agility or Intellect]+7,311 Stamina\n+ 624 Critical Strike\n+ 468 Mastery\nDurability 55 / 55\nEquip: Your spells and abilities have a chance to bring the power of the Light to bear against your foes. A Spark of Beledar judges them, dealing 86350 Radiant damage while marking them. Your next Spark against them will consume the mark to deal an additional 74015 Radiant damage.\n80" }
entries[444074] = { ["name"] = "Horsemen's Aid", ["text"] = "While at your aid, the Horsemen will occasionally cast Anti-Magic Shell on you and themselves at 80% effectiveness.\n\nYou may only benefit from this effect every 45 sec." }
entries[444075] = { ["name"] = "Carapace-Backed Hide", ["text"] = "2 sec cast\nReagents:\nHoned Bone Shards (5), Mosswool Thread (5), Thunderous Hide , Sunless Carapace\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Leatherworking (25)\nCost:\n130\n\nCarapace-Backed Hide\nCrafting Reagent\n\"Crafted by players with the Leatherworking skill. Can be bought and sold on the Auction House.\"" }
