entries[444192] = { ["name"] = "Darkmoon Sigil: Ascension", ["text"] = "3.5 sec cast\nReagents:\nDarkmoon Deck: Ascension , Writhing Sample (8), Boundless Cipher (4), Shadow Ink (4)\nOptional Reagents:\nSpecialization:\n\nDarkmoon Sigil: Ascension\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Gain Ascendance every 8 seconds spent in combat.\n\nAscendance grants 4 of a random secondary stat for 15 sec, stacking up to 10 times.\n\nThis is a Nerubian embellishment.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n\"Can be bought and sold on the Auction House.\"" }
entries[444193] = { ["name"] = "Darkmoon Sigil: Radiance", ["text"] = "3.5 sec cast\nReagents:\nDarkmoon Deck: Radiance , Writhing Sample (8), Boundless Cipher (4), Apricate Ink (4)\nOptional Reagents:\nSpecialization:\nArchival Additions - Darkmoon Sigil: Radiance\n\nDarkmoon Sigil: Radiance\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Your damaging spells and abilities have the chance to ignite your target with Radiant Focus for 15 sec.\n\nAfter dealing up to 18842 damage to the target, the focused energies ignite you with Radiance, granting between ( 35 * .5) to 35 of your highest Secondary stat based on damage dealt for 15 sec.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n\"Can be bought and sold on the Auction House.\"" }
entries[444194] = { ["name"] = "Darkmoon Sigil: Symbiosis", ["text"] = "3.5 sec cast\nReagents:\nDarkmoon Deck: Symbiosis , Writhing Sample (8), Boundless Cipher (4), Shadow Ink (4)\nOptional Reagents:\nSpecialization:\nArchival Additions - Darkmoon Sigil: Symbiosis\n\nDarkmoon Sigil: Symbiosis\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Every 10 seconds in combat take 1% of your maximum Health as Nature damage and gain a stack of Symbiosis, granting 3 Versatility for 20 sec stacking up to 5 times.\n\nThis is a Nerubian embellishment.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n\"Can be bought and sold on the Auction House.\"" }
entries[444195] = { ["name"] = "Darkmoon Sigil: Vivacity", ["text"] = "3.5 sec cast\nReagents:\nDarkmoon Deck: Vivacity , Writhing Sample (8), Boundless Cipher (4), Apricate Ink (4)\nOptional Reagents:\nSpecialization:\nArchival Additions - Darkmoon Sigil: Vivacity\n\nDarkmoon Sigil: Vivacity\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Your damaging spells and abilities have the chance to grant Vivaciousness, increasing secondary stats by 4 and Speed or Avoidance by 2 based on the school it was activated from.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n\"Can be bought and sold on the Auction House.\"" }
