entries[444217] = { ["name"] = "Contract: Assembly of the Deeps", ["text"] = "3.5 sec cast\nReagents:\nFresh Parchment , Shadow Ink (25)\nOptional Reagents:\nVendor:\nWaxmonger Squick\nZone:\nThe Ringing Deeps\nCost:\n150\n\nContract: Assembly of the Deeps\n\nUse: Sign a contract with the Assembly of the Deeps that allows you to gain 5 reputation with them every time you complete a world quest in Khaz Algar until the next weekly reset.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n70\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"" }
entries[444218] = { ["name"] = "Contract: Hallowfall Arathi", ["text"] = "3.5 sec cast\nReagents:\nFresh Parchment , Apricate Ink (25)\nOptional Reagents:\nVendor:\nAuralia Steelstrike\nZone:\nHallowfall\nCost:\n150\n\nContract: Hallowfall Arathi\n\nUse: Sign a contract with the Hallowfall Arathi that allows you to gain 5 reputation with them every time you complete a world quest in Khaz Algar.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n70\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"" }
entries[444219] = { ["name"] = "Contract: The Severed Threads", ["text"] = "3.5 sec cast\nReagents:\nFresh Parchment , Shadow Ink (25)\nOptional Reagents:\nVendor:\nLady Vinazian\nZone:\nAzj-Kahet\nCost:\n150\n\nVendor:\nY'tekhi\nZone:\nAzj-Kahet\nCost:\n150\n\nContract: The Severed Threads\n\nUse: Sign a contract with The Severed Threads that allows you to gain 3 reputation with The General, The Vizier, and The Weaver every time you complete a world quest in Khaz Algar.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n70\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"" }
entries[444220] = { ["name"] = "Contract: Council of Dornogal", ["text"] = "3.5 sec cast\nReagents:\nFresh Parchment , Apricate Ink (25)\nOptional Reagents:\nVendor:\nAuditor Balwurz\nZone:\nIsle of Dorn\nCost:\n150\n\nContract: Council of Dornogal\n\nUse: Sign a contract with the Council of Dornogal that allows you to gain 5 reputation with them every time you complete a world quest in Khaz Algar until the next weekly reset.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n70\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"" }
entries[444221] = { ["name"] = "Shadow Ink", ["text"] = "3.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nDistilled Algari Freshwater (20), Orbinid Pigment (5), Blossom Pigment (5)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Inscription (15)\nCost:\n140\n\nShadow Ink\nCrafting Reagent\n\nProvides the following property: DNT does something awesome\n\"A cool ink crafted by players with the Inscription skill. Can be bought and sold on the Auction House.\"" }
