entries[444248] = { ["name"] = "Summon Mograine", ["text"] = "Instant\nSpending Runes has a chance to call forth the aid of a Horsemen for 10 sec.\n\nMograine\nCasts Death and Decay at his location that follows his position.\n\nWhitemane\nCasts Undeath on your target dealing (9.15376% of Attack Power) Shadowfrost damage per stack every 3 sec, for 24 sec. Each time Undeath deals damage it gains a stack. Cannot be refreshed.\n\nTrollbane\nCasts Chains of Ice on your target slowing their movement speed by 40% and increasing the damage they take from you by 5% for 8 sec.\n\nNazgrim\nWhile Nazgrim is active you gain Apocalyptic Conquest, increasing your Strength by 5%." }
entries[444249] = { ["name"] = "Fire Breath", ["text"] = "100 yd range\nInstant\nInhale, stoking your inner flame. Release to exhale, burning enemies in a cone in front of you for [((163.409% of Spell Power)) + ((39.4834% of Spell Power) * (10 + 0 ))] Fire damage, reduced beyond 5 targets. [ Sands of Time : Increases the duration of your active Ebon Might effects by 2 sec ]\nEmpowering causes more of the damage to be dealt immediately instead of over time.\n\nI: Deals [(163.409% of Spell Power)] damage instantly and [(39.4834% of Spell Power) * (10 + 0 )] over (20 + 0 ) sec.\n\nII: Deals [(163.409% of Spell Power) + ((39.4834% of Spell Power) * 3)] damage instantly and [(39.4834% of Spell Power) * (7 + 0 )] over (14 + 0 ) sec.\n\nIII: Deals [(163.409% of Spell Power) + ((39.4834% of Spell Power) * 6)] damage instantly and [(39.4834% of Spell Power) * (4 + 0 )] over (8 + 0 ) sec." }
entries[444250] = { ["name"] = "Lightning Torrent", ["text"] = "Unlimited range\nInstant\nUpon reaching 100 energy, Kyrioss flies to the center of the room and overcharges itself with lightning energy, inflicting 1212225 Nature damage and striking them with Grounding Bolt every 3 sec for 15 sec. Also unleashes 4 torrents of lightning. Touching these torrents inflicts 19395595 Nature damage and stuns the target for 6 sec." }
entries[444251] = { ["name"] = "Summon Whitemane", ["text"] = "Instant\nSpending Runes has a chance to call forth the aid of a Horsemen for 10 sec.\n\nMograine\nCasts Death and Decay at his location that follows his position.\n\nWhitemane\nCasts Undeath on your target dealing (9.15376% of Attack Power) Shadowfrost damage per stack every 3 sec, for 24 sec. Each time Undeath deals damage it gains a stack. Cannot be refreshed.\n\nTrollbane\nCasts Chains of Ice on your target slowing their movement speed by 40% and increasing the damage they take from you by 5% for 8 sec.\n\nNazgrim\nWhile Nazgrim is active you gain Apocalyptic Conquest, increasing your Strength by 5%." }
entries[444252] = { ["name"] = "Summon Nazgrim", ["text"] = "Instant\nSpending Runes has a chance to call forth the aid of a Horsemen for 10 sec.\n\nMograine\nCasts Death and Decay at his location that follows his position.\n\nWhitemane\nCasts Undeath on your target dealing (9.15376% of Attack Power) Shadowfrost damage per stack every 3 sec, for 24 sec. Each time Undeath deals damage it gains a stack. Cannot be refreshed.\n\nTrollbane\nCasts Chains of Ice on your target slowing their movement speed by 40% and increasing the damage they take from you by 5% for 8 sec.\n\nNazgrim\nWhile Nazgrim is active you gain Apocalyptic Conquest, increasing your Strength by 5%." }
