entries[444257] = { ["name"] = "Thunderous Drums", ["text"] = "Instant 5 min cooldown\nIncreases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism, or similar effects again for 10 min." }
