entries[444266] = { ["name"] = "Bronzebeard Family Compass", ["text"] = "Instant 2 min cooldown\nGet your bearings and meet up with Brann, who heroically swoops in to deliver a for 12435 Physical damage then granting you 305 Primary Stat for 10 sec before exiting.\n\nIf already by your side Brann will proudly direct you towards adventure! Immediately repositioning, granting himself 50% additional damage for 10 sec, and performing a .\n\n:" }
