entries[444755] = { ["name"] = "Bubbling Wax", ["text"] = "3 sec cast\nRequires Main Hand, Off-hand, One-Hand, Ranged, Ranged, Two-Hand\nCoats your weapons in a Bubbling Wax that lasts for until canceled. Applying poisonous effects to your target has a chance to spill a 4 yd wide pool of boiling wax on top of the target, dealing 297 Fire damage split between enemies.\n\nDamage is increased for each enemy struck, up to 5 enemies." }
