entries[444767] = { ["name"] = "Slayer's Dominance", ["text"] = "Approximately 7 procs per minute\nYour attacks against your primary target have a high chance to overwhelm their defenses and trigger a Slayer's Strike, dealing (333.5% of Attack Power) Physical damage and applying Marked for Execution, increasing the damage they take from your next Execute by 15%. Stacks 3 times." }
entries[444769] = { ["name"] = "Imminent Demise", ["text"] = "Every 3 Slayer's Strikes you gain Sudden Death.\n\nUsing Sudden Death accelerates your next Bladestorm, striking 1 additional time (max 3). Bladestorm's total duration is unchanged." }
entries[444770] = { ["name"] = "Death Drive", ["text"] = "You heal for 15% of damage dealt by Sudden Death." }
entries[444771] = { ["name"] = "Show No Mercy", ["text"] = "Marked for Execution increases the critical strike chance and critical strike damage of your next Execute on the target by 15%." }
entries[444772] = { ["name"] = "Overwhelming Blades", ["text"] = "Each strike of Bladestorm applies Overwhelmed to all enemies affected, increasing damage you deal to them by 1 % for 20 sec, max 10 stacks." }
entries[444773] = { ["name"] = "Fierce Followthrough", ["text"] = "Fury\nBloodthirst critical strikes increase the damage of your next Bloodthirst by 20%.\n\nArms\nMortal Strike critical strikes increase the damage of your next Mortal Strike by 20%." }
entries[444774] = { ["name"] = "Opportunist", ["text"] = "Arms\nWhen Overpower has its cooldown reset by Tactician, your next Overpower deals 25% additional damage and 25% additional critical damage.\n\nFury\nWhen Raging Blow resets its own cooldown, your next Raging Blow deals 20% additional damage and 20% additional critical damage." }
entries[444775] = { ["name"] = "Reap the Storm", ["text"] = "Fury\nBloodthirst has a 20% chance to cause you to unleash a flurry of steel, striking all nearby enemies for (371.11% of Attack Power) Physical damage and applying Overwhelmed. Deals reduced damage beyond 8 targets.\n\nArms\nMortal Strike and Cleave when it hits 3 or more targets have a 20% chance to cause you to unleash a flurry of steel, striking all nearby enemies for (371.11% of Attack Power) Physical damage and applying Overwhelmed. Deals reduced damage beyond 8 targets.\n\n(Proc chance: 20%, 500ms cooldown)" }
entries[444776] = { ["name"] = "Relentless Pursuit", ["text"] = "Charge increases your movement speed by 70% for 3 sec.\n\nCharge removes all movement impairing effects, this effect cannot occur more than once every 30 sec." }
entries[444777] = { ["name"] = "Vicious Agility", ["text"] = "Heroic Leap reduces the cooldown of Charge by 5 sec and Charge reduces the cooldown of Heroic Leap by 2 sec." }
entries[444778] = { ["name"] = "Culling Cyclone", ["text"] = "Each strike of Bladestorm deals an additional 10% damage evenly split across all targets." }
entries[444779] = { ["name"] = "Slayer's Malice", ["text"] = "Arms\nOverpower damage increased by 30%.\n\nFury\nRaging Blow damage increased by 30%." }
entries[444780] = { ["name"] = "Unrelenting Onslaught", ["text"] = "When you Execute a target that you've Marked for Execution, you both reduce the cooldown of Bladestorm by 5 sec and apply 2 stacks of Overwhelmed to the target per stack of Marked for Execution consumed.\n\nYou can use Pummel and Storm Bolt while Bladestorming." }
entries[444784] = { ["name"] = "Phantasmal Image", ["text"] = "Your Mirror Image summons one extra clone.\nMirror Image now reduces all damage taken by an additional 5%." }
entries[444785] = { ["name"] = "Bloody Perch", ["text"] = "Instant\nA small, crimson scaled fish that finds its way into waters throughout Khaz Algar. When threatened, its gills expel a viscous ink that closely resembles blood.\n\nSpecial:\n\nBloody Chum\n\nTossing this particular fish back into the waters of Khaz Algar can activate this mechanism, coating yourself in pheromones that can catch elusive Sanguine Dogfish.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Siren Isle\n- K'aresh Oasis\n\nFishing Pools:\n\n- Swarm of Slum Sharks\n- Blood in the Water\n- Festering Rotpool\n- Bloody Perch Swarm\n- Calm Surfacing Ripple\nProfession:\nFishing" }
entries[444786] = { ["name"] = "Crystalline Sturgeon", ["text"] = "5 yd range\nInstant\nA sleek and elongated body that effortlessly navigates the waters of Khaz Algar. Much larger in size compared to it's cousin, the Bismuth Bitterling, this ancient fish tends to follow schools of this fish in an effort to absorb nutrients dislodged by the fish.\n\nSpecial:\n\nPerception\n\nToss this fish back in the water and increase your Khaz Algar Perception.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Siren Isle\n\nFishing Pools:\n\n- Glimmerpool\nProfession:\nFishing" }
entries[444787] = { ["name"] = "Bismuth Bitterling", ["text"] = "5 yd range\n3.2 sec cast\nSmall with a grimacing expression its hard outer scales closely resemble Bismuth. These scales trap minerals and other debris which are then transported throughout the waters of Khaz Algar. A very common fish but nonetheless important in helping the local flora thrive.\n\nSpecial:\n\nChum\n\nToss this fish back in the water and increase your Fishing Skill.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Siren Isle\n\nFishing Pools:\n\n- Glimmerpool\nProfession:\nFishing" }
entries[444788] = { ["name"] = "Nibbling Minnow", ["text"] = "5 yd range\n3.2 sec cast\nAn unsuspecting minnow which could lead an inexperienced angler to believe its value is marginal. However, rumor has it that these fish tend to congregate towards especially shiny objects and nibble at the grime it collects.\n\nSpecial:\n\nPerception\n\nToss this fish back in the water and increase your Khaz Algar Perception.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Azj-Kahet\n- Siren Isle\n- Undermine\n- K'aresh Oasis\n\nFishing Pools:\n\n- Calm Surfacing Ripple\nProfession:\nFishing" }
entries[444789] = { ["name"] = "Whispering Stargazer", ["text"] = "5 yd range\n3.2 sec cast\nNotably forming packed swarms, this fish gets its namesake from the friction of its inky black scales oscillating against each other. These vibrations act as a deterrent for predators and create an audible sound that can be heard above the water.\n\nSpecial:\n\nWhispers of the Deep\n\nUse the Whispering Stargazer to draw out Slumbering Coelacanths from the depths of Azj-Kahet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Siren Isle\n- K'aresh Oasis\n\nFishing Pools:\n\n- Stargazer Swarm\nProfession:\nFishing" }
entries[444790] = { ["name"] = "Goldengill Trout", ["text"] = "5 yd range\n3.2 sec cast\nThe cuts in its gills shine with an iridescent gold. Anglers share its fable as a bringer of good fortune and calm seas.\n\nSpecial:\n\nPerception\n\nReeling this fish in will increase your Khaz Algar Perception.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Azj-Kahet\n- Siren Isle\n- Undermine\n- K'aresh Oasis\n\nFishing Pools:\n\n- Glimmerpool\n- Festering Rotpool\n- Infused Ichor Spill\nProfession:\nFishing" }
entries[444791] = { ["name"] = "Specular Rainbowfish", ["text"] = "5 yd range\n3.2 sec cast\nVaricolored blood coursing underneath translucent scales gives this fish its rainbow appearance. Aside from the culinary uses provided by its meat, Rainbowfish blood is noted to be nearly identical to the Nacreous Pigment used by Scribes.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce Fresh Fillet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Siren Isle\n- K'aresh Oasis\n\nFishing Pools:\n\n- Glimmerpool\nProfession:\nFishing" }
entries[444792] = { ["name"] = "Dilly-Dally Dace", ["text"] = "5 yd range\n3.2 sec cast\nA mischievous fish that zips throughout Khaz Algar. Often mistaken for a Nibbling Minnow or a Regal Dottyback, its speed and size creates a habit of finding itself where it shouldn't be.\n\nSpecial:\n\nChum\n\nToss this fish back in the water and increase your Fishing Skill.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Siren Isle\n- K'aresh Oasis\n\nFishing Pools:\n\n- Calm Surfacing Ripple\n- Blood in the Water\n- Festering Rotpool\nProfession:\nFishing" }
entries[444793] = { ["name"] = "Dornish Pike", ["text"] = "5 yd range\n3.2 sec cast\nAn unassuming creature whose spotted exterior camouflages attacks from above as it preys on smaller fish below. Its large, meaty exterior both bullies nearby Crystalline Sturgeon and provides an excellent source of Fresh Fillet.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce Fresh Fillet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Siren Isle\n\nFishing Pools:\n\n- Calm Surfacing Ripple\nProfession:\nFishing" }
entries[444794] = { ["name"] = "Roaring Anglerseeker", ["text"] = "5 yd range\n3.2 sec cast\nAn aggressive fish that tends to congregate where Anglers are. Its powerful tailfin and muscular body rip through waves creating an audible roar.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce Fresh Fillet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Azj-Kahet\n- Siren Isle\n\nFishing Pools:\n\n- Anglerseeker Torrent\nProfession:\nFishing" }
entries[444795] = { ["name"] = "Arathor Hammerfish", ["text"] = "5 yd range\n3.2 sec cast\nThe crown on its head acts as a formidable weapon when propelled by its massive fins. With scales that shine of a similar Arathi hue, its no wonder this muscular fish bears its namesake.\n\nSpecial:\n\nDrop the Hammer\n\nSmack your enemy with the Hammerfish and stun it for 1 sec. Only usable outdoors in Khaz Algar.\n\nAreas you can find this fish:\n\n- Hallowfall\n\nFishing Pools:\n\n- Blood in the Water\nProfession:\nFishing" }
entries[444796] = { ["name"] = "Regal Dottyback", ["text"] = "5 yd range\n3.2 sec cast\nHues of crimson and magenta stripe across its small but mighty torso. A particularly rare fish of the royal court, this aggressive fish protects the waters around the Queen's Lurefish from the likes of Corrupted Ghoulfish.\n\nSpecial:\n\nRoyal Chum\n\nWard away Corrupted Ghoulfish and create safe water for Queen's Lurefish.\n\nAreas you can find this fish:\n\n- Hallowfall\n- Azj-Kahet\n\nFishing Pools:\n\n- Royal Ripple\nProfession:\nFishing" }
entries[444797] = { ["name"] = "Kaheti Slum Shark", ["text"] = "5 yd range\n3.2 sec cast\nIn the depths of Azj-Kahet this creature glides across the floor with a silhouette that is barely discernible from the murky depths. This calculated predator can leave even the most experienced angler counting their blessings.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce a large amount of Fresh Fillet.\n\nAreas you can find this fish:\n\n- Hallowfall\n- Azj-Kahet\n\nFishing Pools:\n\n- Blood in the Water\n- Slum Shark Swarm\nProfession:\nFishing" }
entries[444798] = { ["name"] = "Pale Huskfish", ["text"] = "5 yd range\n3.2 sec cast\nOften mistaken for a Corrupted Ghoulfish, this large fish is an Angler's best friend. Drawn to mineral on the floors of waterbeds the Pale Huskfish has a propensity to gulp nestled treasures.\n\nSpecial:\n\nHuskfish Stomach\n\nOpen up the contents of the fish in the hopes for treasure.\n\nAreas you can find this fish:\n\n- Azj-Kahet\n- Undermine\n\nFishing Pools:\n\n- Infused Ichor Spill\n- Festering Rotpool\nProfession:\nFishing" }
entries[444799] = { ["name"] = "Sanguine Dogfish", ["text"] = "5 yd range\n3.2 sec cast\nA master of ambush, the Sanguine Dogfish patiently tails lesser fish before positioning its crimson fins for a burst of speed. This large, elusive fish is drawn primarily to schools of Bloody Perch.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce a large amount of Fresh Fillet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Hallowfall\n- Azj-Kahet\n- Siren Isle\n- K'aresh Oasis\n\nFishing Pools:\n\n- Bloody Perch Swarm\n- Blood in the Water\nProfession:\nFishing" }
entries[444800] = { ["name"] = "Spiked Sea Raven", ["text"] = "5 yd range\n3.2 sec cast\nIts body is adorned with sharp spines protruding from various angles, resembling a fearsome armor. These spines serve as both protection and camouflage amidst the rocky seabed where it often dwells. Despite its formidable appearance, it moves with surprising grace, maneuvering effortlessly through underwater crevices and caves.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce a large amount of Fresh Fillet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- Hallowfall\n- Siren Isle\n\nFishing Pools:\n\n- Calm Surfacing Ripple\n- Glimmerpool\n- Stargazer Swarm\n- Anglerseeker Torrent\nProfession:\nFishing" }
entries[444801] = { ["name"] = "Queen's Lurefish", ["text"] = "5 yd range\n3.2 sec cast\nIts elongated body is adorned with iridescent scales that shimmer with a multitude of colors. A bioluminescent lure dangles from its forehead akin to a glowing jewel. With grace, this fish glides effortlessly throughout the inky depths of Khaz Algar. Its keen senses allowing it to thrive in the dark.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce a large amount of Fresh Fillet.\n\nAreas you can find this fish:\n\n- Hallowfall\n- Azj-Kahet\n\nFishing Pools:\n\n- Royal Ripple\nProfession:\nFishing" }
entries[444802] = { ["name"] = "Cursed Ghoulfish", ["text"] = "5 yd range\nInstant\nWarped by the blood of the Old Gods, its sickly pale skin stretches over its skeletal body. Anglers across Khaz Algar speak of this fish as a messenger of doom, cursing any Angler unfortunate enough to reel it in. Staring into the eyes of this creature will only elaborate its depravity as any reflection is consumed by the abyss.\n\nCatching this fish will cast:\n\nGhoulfish Curse\n\nHowever, hope is not lost. Where anglers avoid the Cursed Ghoulfish, chefs see opportunity. Salvaging this fish could elaborate useful benefits for your belly and your Fishing Skill.\n\nAreas you can find this fish:\n\n- Anywhere an overconfident Algari Angler casts their line.\n\nFishing Pools:\n\n- All Pools\nProfession:\nFishing" }
entries[444803] = { ["name"] = "Awoken Coelacanth", ["text"] = "5 yd range\nInstant\nA humble, dormant creature. When awake, its scales shimmer with reflective brilliance despite being in contact with little light. A quiet majesty and a fitting goal for any aspiring Angler.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce a large amount of Fresh Fillet.\n\nAreas you can find this fish:\n\n- Azj-Kahet\n- K'aresh Oasis\nProfession:\nFishing" }
entries[444806] = { ["name"] = "Fury of the Aldrachi", ["text"] = "Instant\nConsuming [ Havoc : 6 /\n\nVengeance\n20 ] Soul Fragments or casting The Hunt converts your next Throw Glaive into Reaver's Glaive.\n\nReaver's Glaive :\nThrow a glaive enhanced with the essence of consumed souls at your target, dealing (345% of Attack Power) Physical damage and ricocheting to 2 additional enemies.\n\nBegins a well-practiced pattern of glaivework, enhancing your next [ Havoc : Chaos Strike / Fracture / Shear ] and [ Havoc : Blade Dance /\n\nVengeance\nSoul Cleave ]\nThe enhanced ability you cast first deals 10% increased damage, and the second deals 20% increased damage." }
