entries[444810] = { ["name"] = "Art of the Glaive", ["text"] = "8 yd range\nInstant\nVengeance\nConsuming a Soul Fragment causes your next to deal (40% of Attack Power) additional Physical damage.\n\nHavoc\nConsuming a Soul Fragment causes your next Chaos Strike to deal (40% of Attack Power) additional Physical damage.\n\nFelblade consumes up to 5 nearby Soul Fragments." }
