entries[445024] = { ["name"] = "Whirling Elements", ["text"] = "Enhancement\nElemental motes orbit around your Surging Totem. Your abilities consume the motes for enhanced effects.\n\nAir: [ Enhancement : Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes 3 Surging Bolts at your Surging Totem /\n\nElemental, Restoration\nThe cast time of your next healing spell is reduced by 40% ]\nEarth: [ Enhancement : Direct damage of your next Flame Shock is increased by 300% and it is applied to 5 nearby enemies /\n\nElemental, Restoration\nYour next Chain Heal applies Earthliving at 150% effectiveness to all targets hit ]\nFire: Your next Lava Lash or Fire Nova grants you Hot Hand for 6 sec.\n\nRestoration\nElemental motes orbit around your Surging Totem. Your abilities consume the motes for enhanced effects.\n\nWater: Your next Healing Wave or Healing Surge also heals an ally inside of your Healing Rain at 100% effectiveness.\n\nAir: [ Enhancement : Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes 3 Surging Bolts at your Surging Totem /\n\nElemental, Restoration\nThe cast time of your next healing spell is reduced by 40% ]\nEarth: [ Enhancement : Direct damage of your next Flame Shock is increased by 300% and it is applied to 5 nearby enemies /\n\nElemental, Restoration\nYour next Chain Heal applies Earthliving at 150% effectiveness to all targets hit ]" }
entries[445025] = { ["name"] = "Totemic Rebound", ["text"] = "Approximately 10 procs per minute\nRestoration\nChain Heal now jumps to a nearby totem within 20 yards once it reaches its last target, causing the totem to cast Chain Heal on an injured ally within 30 yards for (150% of Spell Power). Jumps to 2 nearby targets within 20 yards.\n\nEnhancement\nLightning Bolt, Chain Lightning and Elemental Blast has a chance to unleash a Surging Bolt at your Surging Totem, increasing the totem's damage by 10%, and then redirecting the bolt to your target for (92% of Attack Power) Nature damage. The damage bonus effect can stack." }
entries[445026] = { ["name"] = "Oversized Totems", ["text"] = "Increases the size and radius of your totems by 15%, and the health of your totems by 30%." }
entries[445027] = { ["name"] = "Swift Recall", ["text"] = "Successfully removing a harmful effect with Tremor Totem or Poison Cleansing Totem, or controlling an enemy with Capacitor Totem or Earthgrab Totem reduces the cooldown of the totem used by 5 sec.\n\nCannot occur more than once every 20 sec per totem." }
entries[445028] = { ["name"] = "Imbuement Mastery", ["text"] = "Enhancement\nIncreases the chance for Windfury Weapon to trigger by 5% and increases its damage by 8%.\n\nWhen Flametongue Weapon triggers from Windfury Weapon attacks, it has a chance to gather a whirl of flame around the target, dealing 300% of its damage to all nearby enemies.\n\nRestoration\nIncreases the duration of your Earthliving effect by 3 sec." }
entries[445029] = { ["name"] = "Amplification Core", ["text"] = "While Surging Totem is active, your damage and healing done is increased by 3%." }
entries[445030] = { ["name"] = "Oversurge", ["text"] = "Restoration\nSurging Totem deals 50% more damage during Ascendance.\n\nEnhancement\nSurging Totem deals 50% more damage during Ascendance." }
entries[445031] = { ["name"] = "Wind Barrier", ["text"] = "If you have a totem active, your totem grants you a shield absorbing (Total Health * 6 / 100) damage for 30 sec every 30 sec." }
entries[445032] = { ["name"] = "Pulse Capacitor", ["text"] = "Enhancement\nIncreases the damage of Surging Totem by 18%.\n\nRestoration\nIncreases the healing done by Surging Totem by 25%." }
entries[445033] = { ["name"] = "Supportive Imbuements", ["text"] = "Enhancement\nIncreases the critical strike chance of Flametongue Weapon by 25%, and its critical strike damage by 100%.\n\nRestoration\nLearn a new weapon imbue, Tidecaller's Guard.\n\nTidecaller's Guard\nImbue your shield with the element of Water for 1 hour. Your healing done is increased by 2.0% and the duration of your Healing Stream Totem and Cloudburst Totem is increased by 3.0 sec." }
entries[445034] = { ["name"] = "Lively Totems", ["text"] = "Enhancement\nLava Lash has a chance to summon a Searing Totem to hurl Searing Bolts that deal (65.205% of Spell Power) Fire damage to a nearby enemy. Lasts 8 sec.\n\nFrost Shocks empowered by Hailstorm, Lava Lash, and Fire Nova cause your Searing totems to shoot a Searing Volley at up to 5 nearby enemies for (92.736% of Spell Power) Fire damage.\n\nRestoration\nWhen you summon a Healing Tide Totem, Healing Stream Totem, Cloudburst Totem, or Spirit Link Totem you cast a free instant Chain Heal at 100% effectiveness." }
entries[445035] = { ["name"] = "Reactivity", ["text"] = "Enhancement\nWhile Hot Hand is active Lava Lash shatters the earth, causing a Sundering at 50% effectiveness.\n\nSunderings from this effect do not Incapacitate.\n\nRestoration\nYour Healing Stream Totems now also heals a second ally at 100% effectiveness.\n\nCloudburst Totem stores 25% additional healing." }
