entries[445317] = { ["name"] = "Stormrider's Fury", ["text"] = "3.5 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nRinging Deeps Ingot , Storm Dust (50), Gleaming Shard (5), Refulgent Crystal\nOptional Reagents:\nEarthen Enhancements - Wondrous Weapons\n\nPermanently enchants a weapon to sometimes grant you Storm's Fury, bestowing 16 Haste to you for 12 sec. Cannot be applied to items lower than level 70.\nProfession Trainer:\nKhaz Algar Enchanting (55)\nCost:\n180\n\nEnchant Weapon - Stormrider's Fury\n\nUse: Earthen Enhancements - Wondrous Weapons\n\nPermanently enchants a weapon to sometimes grant you Storm's Fury, bestowing 24 Haste to you for 12 sec. Cannot be applied to items lower than level 70.\n70" }
entries[445318] = { ["name"] = "Oil of Beledar's Grace", ["text"] = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Crystalline Powder (2), Storm Dust (10), Gleaming Shard\nOptional Reagents:\nSpecialization:\nEphemerals, Enrichments, and Equipment - Optimal Oils\n\nOil of Beledar's Grace\n\nUse: Coat your weapon in an oil that emits a warm light. The oil has a chance to resonate with your healing, healing an additional 1419 Health to the target.\n\nLasts 120 min.\n68\n\"The vial of oil radiates with the warm light of Beledar.\"" }
entries[445319] = { ["name"] = "Gleeful Glamour - Orc", ["text"] = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nLeyline Residue , Viridescent Spores , Storm Dust (5)\nOptional Reagents:\nSpecialization:\nEphemerals, Enrichments, and Equipment - Deceptive Decorations\n\nUse: Don the mask, magically altering your appearance to that of another one of Azeroth's residents.\n\nLasts 20-60 min. based on the quality of the Gleeful Glamour." }
entries[445320] = { ["name"] = "Radiant Haste", ["text"] = "3.5 sec cast\nRequires Ring\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (30), Gleaming Shard (5)\nOptional Reagents:\nArathor Alterations - Accentuated Accessories\n\nPermanently enchants a ring with Beledar's radiance, increasing Haste by 15. Cannot be applied to items lower than level 70.\nDrop:\nPrioress Murrpray\nZone:\nPriory of the Sacred Flame\n\nTreasure:\nChallenger's Cache\nZone:\nThe Dawnbreaker\n\nEnchant Ring - Radiant Haste\n\nUse: Arathor Alterations - Accentuated Accessories\n\nPermanently enchants a ring with Beledar's radiance, increasing Haste by 15. Cannot be applied to items lower than level 70.\n70" }
entries[445321] = { ["name"] = "Oathsworn's Strength", ["text"] = "3.5 sec cast 2\nRequires Chest, Chest\nTools: Runed Enchanting Rod\nReagents:\nCrystalline Powder (10), Ringing Deeps Ingot , Storm Dust (75), Gleaming Shard (10), Refulgent Crystal\nOptional Reagents:\nEarthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece to increase your Strength by 24 and Stamina by 12. Cannot be applied to items lower than level 70.\nDrop:\nAwakening the Machine\n\nEnchant Chest - Oathsworn's Strength\n\nUse: Earthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece to increase your Strength by 24 and Stamina by 12. Cannot be applied to items lower than level 70.\n70" }
entries[445322] = { ["name"] = "Council's Intellect", ["text"] = "3.5 sec cast 2\nRequires Chest, Chest\nTools: Runed Enchanting Rod\nReagents:\nCrystalline Powder (10), Leyline Residue (5), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal\nOptional Reagents:\nEarthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece to increase your Intellect by 24 and mana pool by 3%. Cannot be applied to items lower than level 70.\nVendor:\nAuditor Balwurz\nZone:\nDornogal\nCost:\n150\n\nEnchant Chest - Council's Intellect\n\nUse: Earthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece to increase your Intellect by 24 and mana pool by 3%. Cannot be applied to items lower than level 70.\n70" }
entries[445323] = { ["name"] = "Runed Null Stone Rod", ["text"] = "3.5 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nOptional Reagents:\nVendor:\nLyrendal\nZone:\nDornogal\nCost:\n150\n\nRuned Null Stone Rod\nBinds when picked up\nEnchanting Tool\n+ 125 Random Stat 1\nEquip: +18 Khaz Algar Enchanting Skill\nEquip: You use 1% less Concentration when Concentrating on Khaz Algar Enchanting recipes.\n68\n\"Serves as a runed enchanting rod.\"" }
entries[445324] = { ["name"] = "Enchanted Spearwood Wand", ["text"] = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nStorm Dust (5), Codified Greenwood\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Enchanting (40)\nCost:\n150\n\nEnchanted Spearwood Wand\nBinds when equipped\nRanged Wand\n270 - 451 Shadow Damage Speed 2.00\n(180.3 damage per second)\n+1,847 Intellect\n+1,162 Stamina\n+ 222 Random Stat 1\n+ 222 Random Stat 2\nDurability 90 / 90\n72" }
entries[445325] = { ["name"] = "Chant of Armored Leech", ["text"] = "3.5 sec cast 2\nRequires Bracers\nTools: Runed Enchanting Rod\nReagents:\nVial of Kaheti Oils , Storm Dust (40), Gleaming Shard (5)\nOptional Reagents:\nNerubian Novelties - Tertiary Trivialities\n\nPermanently enchants bracers with ancient magic that chants with power, granting 38 Leech. Cannot be applied to items lower than level 70.\nVendor:\nIliani\nZone:\nCity of Threads\nCost:\n150\n1500\n\nVendor:\nVenomscribe Xesh XI\nZone:\nCity of Threads\nCost:\n150\n1500\n\nEnchant Bracer - Chant of Armored Leech\n\nUse: Nerubian Novelties - Tertiary Trivialities\n\nPermanently enchants bracers with ancient magic that chants with power, granting 38 Leech. Cannot be applied to items lower than level 70.\n70" }
