entries[445330] = { ["name"] = "Chant of Armored Speed", ["text"] = "3.5 sec cast 2\nRequires Bracers\nTools: Runed Enchanting Rod\nReagents:\nVial of Kaheti Oils , Storm Dust (40), Gleaming Shard (5)\nOptional Reagents:\nNerubian Novelties - Tertiary Trivialities\n\nPermanently enchants bracers with ancient magic that chants with power, granting 46 Speed. Cannot be applied to items lower than level 70.\nSpecialization:\nEverlasting Enchantments - Tertiary Trivialities\n\nEnchant Bracer - Chant of Armored Speed\n\nUse: Nerubian Novelties - Tertiary Trivialities\n\nPermanently enchants bracers with ancient magic that chants with power, granting 46 Speed. Cannot be applied to items lower than level 70.\n70" }
entries[445331] = { ["name"] = "Authority of Air", ["text"] = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\nArathor Alterations - Fortified Flames\n\nPermanently enchants a weapon with the Authority of Air, which sometimes beckons a protective wind to your aid when taking damage that absorbs the next 2013 damage dealt to you. Cannot be applied to items lower than level 70.\nTreasure:\nChallenger's Cache\nZone:\nThe Dawnbreaker\n\nEnchant Weapon - Authority of Air\n\nUse: Arathor Alterations - Fortified Flames\n\nPermanently enchants a weapon with the Authority of Air, which sometimes beckons a protective wind to your aid when taking damage that absorbs the next 2013 damage dealt to you. Cannot be applied to items lower than level 70.\n70" }
