entries[445333] = { ["name"] = "Crystalline Radiance", ["text"] = "3.5 sec cast 2\nRequires Chest, Chest\nTools: Runed Enchanting Rod\nReagents:\nCrystalline Powder (20), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal\nOptional Reagents:\nEarthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece with Earthen rune magic to increase your Primary Stat by 34. Cannot be applied to items lower than level 70.\nSpecialization:\nEverlasting Enchantments - Bolstered Breastplates\n\nEnchant Chest - Crystalline Radiance\n\nUse: Earthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece with Earthen rune magic to increase your Primary Stat by 34. Cannot be applied to items lower than level 70.\n70" }
entries[445334] = { ["name"] = "Chant of Armored Avoidance", ["text"] = "3.5 sec cast 2\nRequires Bracers\nTools: Runed Enchanting Rod\nReagents:\nVial of Kaheti Oils , Storm Dust (40), Gleaming Shard (5)\nOptional Reagents:\nNerubian Novelties - Tertiary Trivialities\n\nPermanently enchants bracers with ancient magic that chants with power, granting 50 Avoidance. Cannot be applied to items lower than level 70.\nVendor:\nIliani\nZone:\nCity of Threads\nCost:\n150\n1500\n\nVendor:\nVenomscribe Xesh XI\nZone:\nCity of Threads\nCost:\n150\n1500\n\nEnchant Bracer - Chant of Armored Avoidance\n\nUse: Nerubian Novelties - Tertiary Trivialities\n\nPermanently enchants bracers with ancient magic that chants with power, granting 50 Avoidance. Cannot be applied to items lower than level 70.\n70" }
entries[445335] = { ["name"] = "Cavalry's March", ["text"] = "3.5 sec cast\nRequires Boots\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (30), Gleaming Shard (5)\nOptional Reagents:\nArathor Alterations - Accentuated Accessories\n\nPermanently enchants a pair of boots with the cavalry's fleetness, increasing mounted speed by 6%. Cannot be applied to items lower than level 70.\nVendor:\nLyrendal\nZone:\nDornogal\nCost:\n150\n\nEnchant Boots - Cavalry's March\n\nUse: Arathor Alterations - Accentuated Accessories\n\nPermanently enchants a pair of boots with the cavalry's fleetness, increasing mounted speed by 6%. Cannot be applied to items lower than level 70.\n70" }
entries[445336] = { ["name"] = "Authority of Storms", ["text"] = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nRinging Deeps Ingot , Bottled Storm (5), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\nEarthen Enhancements - Wondrous Weapons\n\nPermanently enchants a weapon with the Authority of Storms. Your abilities have a chance to imbue you, causing further abilities to sometimes unleash lightning which deals ( 1 * 2014) Nature damage split amongst all enemies hit. Cannot be applied to items lower than level 70.\nSpecialization:\nEverlasting Enchantments - Wondrous Weapons\n\nEnchant Weapon - Authority of Storms\n\nUse: Earthen Enhancements - Wondrous Weapons\n\nPermanently enchants a weapon with the Authority of Storms. Your abilities have a chance to imbue you, causing further abilities to sometimes unleash lightning which deals ( 1 * 2014) Nature damage split amongst all enemies hit. Cannot be applied to items lower than level 70.\n70" }
