entries[445338] = { ["name"] = "Algari Mana Oil", ["text"] = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nLeyline Residue (10), Storm Dust (5)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Enchanting (20)\nCost:\n110\n\nAlgari Mana Oil\n\nUse: Coat your weapon in Algari Mana Oil, increasing your Critical Strike and Haste by 5 for 120 min.\n68\n\"The oil radiates a subtle, but noticeable magical aura.\"" }
entries[445339] = { ["name"] = "Authority of Radiant Power", ["text"] = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\nArathor Alterations - Fortified Flames\n\nPermanently enchants a weapon with the Authority of Radiant Power. Dealing damage has a chance to call upon that authority, smiting your target for ( 1 * 1681) Radiant damage and temporarily increasing your Primary stat by 14. Cannot be applied to items lower than level 70.\nDrop:\nPrioress Murrpray\nZone:\nPriory of the Sacred Flame\n\nEnchant Weapon - Authority of Radiant Power\n\nUse: Arathor Alterations - Fortified Flames\n\nPermanently enchants a weapon with the Authority of Radiant Power. Dealing damage has a chance to call upon that authority, smiting your target for ( 1 * 1681) Radiant damage and temporarily increasing your Primary stat by 14. Cannot be applied to items lower than level 70.\n70" }
entries[445340] = { ["name"] = "Glimmering Versatility", ["text"] = "3.5 sec cast\nRequires Ring\nTools: Runed Enchanting Rod\nReagents:\nStorm Dust (5)\nOptional Reagents:\nArathor Alterations - Accentuated Accessories\n\nPermanently enchants a ring with a glimmer of Beledar, increasing Versatility by 9. Cannot be applied to items lower than level 70.\nProfession Trainer:\nKhaz Algar Enchanting (45)\nCost:\n160\n\nEnchant Ring - Glimmering Versatility\n\nUse: Arathor Alterations - Accentuated Accessories\n\nPermanently enchants a ring with a glimmer of Beledar, increasing Versatility by 9. Cannot be applied to items lower than level 70.\n70" }
entries[445341] = { ["name"] = "Authority of the Depths", ["text"] = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nVial of Kaheti Oils , Writhing Sample (5), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\nNerubian Novelties\n\nPermanently enchants a weapon with the Authority of the Depths. Damaging foes may invoke it, applying Suffocating Darkness which periodically inflicts ( 1 * 242) Shadow damage. The darkness may deepen up to 3 times. Cannot be applied to items lower than level 70.\nDrop:\nQueen Ansurek\nZone:\nNerub-ar Palace\nRecipe:\nPurchasable on the Auction House\n\nEnchant Weapon - Authority of the Depths\n\nUse: Nerubian Novelties\n\nPermanently enchants a weapon with the Authority of the Depths. Damaging foes may invoke it, applying Suffocating Darkness which periodically inflicts ( 1 * 242) Shadow damage. The darkness may deepen up to 3 times. Cannot be applied to items lower than level 70.\n70" }
