entries[445465] = { ["name"] = "Wither", ["text"] = "Destruction\nBestows a vile malediction upon the target, burning the sinew and muscle of its host, dealing (19.8375% of Spell Power) Shadowflame damage immediately and an additional (296.544% of Spell Power) Shadowflame damage over 18 sec.\n\nPeriodic damage generates 1 Soul Shard Fragment and has a 50% chance to generate an additional 1 on critical strikes.\n\nReplaces Immolate.\n\nAffliction\nBestows a vile malediction upon the target, burning the sinew and muscle of its host, dealing (19.8375% of Spell Power) Shadowflame damage immediately and an additional (296.544% of Spell Power) Shadowflame damage over 18 sec.\n\nReplaces Corruption." }
entries[445466] = { ["name"] = "Shatter Essence", ["text"] = "1.5 sec cast\nShatter a magical essence of Khaz Algar to utilize the power within for your Enchanting.\n\nGain the following effect when shattering:\n\nShattered Essence :\nEmpowered by a shattered magical essence of Khaz Algar, increasing Resourcefulness, Ingenuity, and Multicraft while practicing Khaz Algar Enchanting.\nSpecialization:\nSupplementary Shattering" }
entries[445468] = { ["name"] = "Wither", ["text"] = "1.5% of base mana 40 yd range\nInstant\nDestruction\nBestows a vile malediction upon the target, burning the sinew and muscle of its host, dealing (19.8375% of Spell Power) Shadowflame damage immediately and an additional (296.544% of Spell Power) Shadowflame damage over 18 sec .\n\nPeriodic damage generates 1 Soul Shard Fragment and has a 50% chance to generate an additional 1 on critical strikes.\n\nReplaces Immolate.\n\nAffliction\nBestows a vile malediction upon the target, burning the sinew and muscle of its host, dealing (19.8375% of Spell Power) Shadowflame damage immediately and an additional (296.544% of Spell Power) Shadowflame damage over 18 sec .\n\nReplaces Corruption." }
