entries[445475] = { ["name"] = "Surekian Barrage", ["text"] = "Instant\nDraw a bow from the Arsenal to unleash a barrage of arrows in front of you, dealing ( 1 * 1478 ) Shadow damage to all enemies within 20 yards.\n\nUntil the next weapon is drawn, remain stationary to increase your speed by 6% for 6 sec upon moving, increased by an additional 6% every 2 sec, up to 5 times." }
entries[445479] = { ["name"] = "Cinder Nectar", ["text"] = "2 sec cast\nReagents:\nDelver's Waterskin (3), Hot Honeycomb\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 10 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCendvin\nZone:\nIsle of Dorn\nCost:\n120\n\nCinder Nectar\nUse: Restores ( 937500 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n68" }
entries[445480] = { ["name"] = "Pep-In-Your-Step", ["text"] = "2 sec cast\nReagents:\nDelver's Waterskin (5)\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 1 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\nPep-In-Your-Step\nUse: Restores ( 937500 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n\nPep-In-Your-Step\nIf you spend at least 10 seconds drinking you will gain 167 Speed and the ability to walk on water for 10 min.\n68" }
entries[445482] = { ["name"] = "Rockslide Shake", ["text"] = "2 sec cast\nReagents:\nDelver's Waterskin (5), Spongey Scramble (3), Hot Honeycomb , Bismuth (10)\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 10 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\nRockslide Shake\nUse: This isn't blended at all... (5 Min Cooldown)\n68\n\"The perfect Earthen treat for a hot day in Khaz Algar.\"" }
entries[445483] = { ["name"] = "Sticky Sweet Treat", ["text"] = "2 sec cast\nReagents:\nSpongey Scramble (3), Hot Honeycomb , Clumped Flour (5), Coreway Dust (5)\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 10 servings. Actual number of servings will vary based on cooking skill.\nDrop:\nBroodtwister Ovi'nax\nZone:\nNerub-ar Palace\nRecipe:\nPurchasable on the Auction House\n\nSticky Sweet Treat\nUse: Be a kid again! (5 Min Cooldown)\n68\n\"Cinderbee honey from the cave networks above is a delicacy for a young nerubian.\"" }
entries[445484] = { ["name"] = "Melted Candlebar", ["text"] = "2 sec cast\nReagents:\nSpongey Scramble (3), Hot Honeycomb , Clumped Flour (5)\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 10 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\nMelted Candlebar\nUse: What's the harm in trying? (5 Min Cooldown)\n68\n\"A perfect mixture of chewy and crunchy. You can't imagine sharing this with anyone else.\"" }
