entries[445495] = { ["name"] = "Consume Flame", ["text"] = "100 yd range\nInstant\nPreservation\nEngulf consumes 2 sec of Dream Breath from the target, detonating it and healing all nearby targets equal to 900% of the amount consumed, reduced beyond 5 targets.\n\nDevastation\nEngulf consumes 2 sec of Fire Breath from the target, detonating it and damaging all nearby targets equal to 900% of the amount consumed, reduced beyond 5 targets." }
